export function validateSourceCorrections(board){const errors=[],units=new Map(board.units.map(u=>[u.id,u]));for(const [id,c] of Object.entries(board.sourceCorrections??{})){const u=units.get(id);if(!u||c.originalText!==u.text||typeof c.text!=='string'||!c.text.trim()||c.text===u.text||typeof c.reviewer!=='string'||!c.reviewer.trim()||!/^([a-f0-9]{64})$/.test(c.packageHash??'')||typeof c.packageId!=='string'||!c.packageId||typeof c.packageRevision!=='string'||!c.packageRevision||c.sourcePdfHash!==board.pdfHash)errors.push('Invalid reviewed source correction')}return errors}
export function correctedItem(item,board){if(item.status!=='source_supported'||item.refs?.length!==1)return item;const c=board.sourceCorrections?.[item.refs[0]];if(!c||item.text!==c.originalText)return item;return {...item,text:c.text,status:'reviewed_inference',sourceReview:c}}
